  auto GRATING_LOBE_AZIMUTH_DEG__ = GRATING_LOBE_AZIMUTH_DEG ? _fbb.CreateVector<double>(*GRATING_LOBE_AZIMUTH_DEG) : 0;
  auto GRATING_LOBE_ELEVATION_DEG__ = GRATING_LOBE_ELEVATION_DEG ? _fbb.CreateVector<double>(*GRATING_LOBE_ELEVATION_DEG) : 0;
  auto NULLS__ = NULLS ? _fbb.CreateVector<::flatbuffers::Offset<PAPNull>>(*NULLS) : 0;
  auto PRODUCER_ID__ = PRODUCER_ID ? _fbb.CreateString(PRODUCER_ID) : 0;
  auto SIGNATURE__ = SIGNATURE ? _fbb.CreateVector<uint8_t>(*SIGNATURE) : 0;
  auto CANONICAL_JSON_SIGNATURE__ = CANONICAL_JSON_SIGNATURE ? _fbb.CreateVector<uint8_t>(*CANONICAL_JSON_SIGNATURE) : 0;
